import Capacitor
import Foundation
import UIKit

/// Shares a text file generated by the web layer (see src/lib/file-share.ts) through the system share
/// sheet, so the user can save it to Files, AirDrop it or pass it to another app. WKWebView cannot
/// download Blob URLs, so this replaces <a download> inside the iOS app.
/// The file is written to a protected temporary folder and removed once the sheet closes.
@objc(FileSharePlugin)
public class FileSharePlugin: CAPPlugin, CAPBridgedPlugin {
    public let identifier = "FileSharePlugin"
    public let jsName = "FileShare"
    public let pluginMethods: [CAPPluginMethod] = [
        CAPPluginMethod(name: "shareFile", returnType: CAPPluginReturnPromise)
    ]

    private static let allowed = CharacterSet(charactersIn: "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-")
    private let folder = FileManager.default.temporaryDirectory.appendingPathComponent("Exports", isDirectory: true)

    @objc func shareFile(_ call: CAPPluginCall) {
        guard let requested = call.getString("filename"), let content = call.getString("content") else {
            return call.reject("Missing filename or content", "INVALID")
        }
        // Only a plain file name: no folders, no hidden files.
        let name = String(requested.unicodeScalars.filter { Self.allowed.contains($0) })
        guard !name.isEmpty, !name.hasPrefix("."), name.count <= 120, !content.isEmpty else {
            return call.reject("Invalid filename or empty content", "INVALID")
        }

        let url = folder.appendingPathComponent(name)
        do {
            // Earlier exports left behind (e.g. app terminated while sharing) are removed first.
            try? FileManager.default.removeItem(at: folder)
            try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
            try Data(content.utf8).write(to: url, options: [.atomic, .completeFileProtection])
        } catch {
            return call.reject("Writing the export file failed", "WRITE_FAILED")
        }

        DispatchQueue.main.async { [weak self] in
            guard let self, let presenter = self.bridge?.viewController, presenter.presentedViewController == nil else {
                try? FileManager.default.removeItem(at: url)
                return call.reject("The share sheet cannot be shown right now", "UNAVAILABLE")
            }
            let sheet = UIActivityViewController(activityItems: [url], applicationActivities: nil)
            sheet.completionWithItemsHandler = { _, completed, _, error in
                try? FileManager.default.removeItem(at: url)
                if error != nil { return call.reject("Sharing failed", "SHARE_FAILED") }
                call.resolve(["completed": completed])
            }
            // iPad presents the sheet as a popover, which needs an anchor or UIKit raises an exception.
            if let popover = sheet.popoverPresentationController {
                popover.sourceView = presenter.view
                popover.sourceRect = CGRect(x: presenter.view.bounds.midX, y: presenter.view.bounds.midY, width: 0, height: 0)
                popover.permittedArrowDirections = []
            }
            presenter.present(sheet, animated: true)
        }
    }
}
